package main

import (
	"fmt"
	"path/filepath"
)

func isValidFilename(filename string) bool {
	cleanPath := filepath.Clean("/var/songs/" + filename)
	return cleanPath == filepath.Join("/var/songs", filepath.Base(cleanPath))
}

func main() {
	fmt.Println(isValidFilename("peters_mixtape.mp3")) // true
	fmt.Println(isValidFilename("../etc/passwd"))      // false
}
